import java.io.*;
import javax.servlet.http.*;

public class VulnerableServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        // Getting user input from the query parameter
        String userInput = request.getParameter("file");

        // VULNERABLE: Directly concatenating user input to form a file path
        // This allows an attacker to use "../" sequences to access sensitive files
        // (Path Traversal Vulnerability)
        String filePath = "/var/www/data/" + userInput;

        File file = new File(filePath);

        // Reading and returning the file content without validation
        FileInputStream fis = new FileInputStream(file);
        int data;
        while ((data = fis.read()) != -1) {
            response.getOutputStream().write(data);
        }
        fis.close();
    }
}
