import java.io.*;
import javax.servlet.http.*;
import java.nio.file.*;

public class SecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("file");

        // Define the base directory securely
        Path baseDir = Paths.get("/var/www/data/");

        // Resolve the user input against the base directory
        Path resolvedPath = baseDir.resolve(userInput).normalize();

        // Check if the resolved path is still within the base directory
        // This prevents directory traversal attacks
        if (!resolvedPath.startsWith(baseDir)) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid file path");
            return;
        }

        // Safe to read the file now
        File file = resolvedPath.toFile();
        if (file.exists() && file.isFile()) {
            FileInputStream fis = new FileInputStream(file);
            int data;
            while ((data = fis.read()) != -1) {
                response.getOutputStream().write(data);
            }
            fis.close();
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
        }
    }
}
